include <robotics.scad>
// Molicel INR-21700-P42A wrapped steel can. Local: axis along Z, negative base at z=0.
// D = 21.55 mm (datasheet max). Can length = 70.15 max height − 0.5 mm conservative cap.
D = 21.55; L = 69.65; e = 0.4;   // e: small undimensioned edge break (inside envelope)
cap_seat_d = 10.4; cap_seat = 0.2;  // shallow seat for the separate cap body
$fn = 96;
difference() {
  cyl(d = D, h = L, chamfer = e, anchor = BOT);
  up(L - cap_seat) cyl(d = cap_seat_d, h = 1, anchor = BOT);
}

include <robotics.scad>
// Positive terminal: plain flat cap. Diameter and height NOT dimensioned by Molicel;
// conservative Ø10, standing 0.5 mm proud (sits 0.2 mm in a seat) so the cell is 70.15 mm max.
$fn = 64;
cyl(d = 10, h = 0.7, anchor = BOT);
